package com.hotelmanagement.hms.payment.service; import com.hotelmanagement.hms.payment.dto.*; import com.hotelmanagement.hms.payment.model.*; import com.hotelmanagement.hms.payment.repository.*; import com.hotelmanagement.hms.shared.service.OperationScope; import com.hotelmanagement.hms.shared.web.*; import com.hotelmanagement.hms.audit.service.AuditService; import static com.hotelmanagement.hms.identity.authorization.model.PermissionCode.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import java.util.*; import java.math.*;
@Service @Transactional public class CashierShiftService { private final CashierShiftRepository repo; private final OperationScope scope; private final AuditService audit; private final org.springframework.jdbc.core.JdbcTemplate db; public CashierShiftService(CashierShiftRepository r,OperationScope s,AuditService a,org.springframework.jdbc.core.JdbcTemplate d){repo=r;scope=s;audit=a;db=d;} public CashierShiftResponse open(UUID h,UUID b,CashierShiftRequest q){UUID u=scope.branch(h,b,CASHIER_SHIFT_OPEN);if(repo.findByHotelIdAndBranchIdAndCashierUserIdAndStatus(h,b,u,CashierShiftStatus.OPEN).isPresent())throw new ApiException(409,"SHIFT_OPEN","Cashier already has an open shift.");var s=repo.save(CashierShift.open(h,b,u,q.openingFloat(),q.notes()));audit.record(h,b,u,"CASHIER_SHIFT_OPENED","CASHIER_SHIFT",s.getId());return CashierShiftResponse.from(s);} public CashierShiftResponse close(UUID h,UUID b,UUID id,BigDecimal expected,BigDecimal counted){UUID u=scope.branch(h,b,CASHIER_SHIFT_CLOSE);var s=repo.lock(id).filter(x->x.getHotelId().equals(h)&&x.getBranchId().equals(b)).orElseThrow(ApiException::notFound);if(!s.getCashierUserId().equals(u))throw new org.springframework.security.access.AccessDeniedException("Close your own shift.");
var cash=db.queryForObject("select coalesce(sum(e.amount),0) from folio_entries e join payments p on p.id=e.source_id where e.hotel_id=? and e.branch_id=? and e.actor_id=? and e.created_at>=? and p.method='CASH' and e.kind in ('PAYMENT','REFUND')",BigDecimal.class,h,b,u,java.sql.Timestamp.from(s.getOpenedAt()));
var outgoing=db.queryForObject("select coalesce(sum(amount),0) from vendor_payments where hotel_id=? and branch_id=? and actor_id=? and created_at>=? and method='CASH'",BigDecimal.class,h,b,u,java.sql.Timestamp.from(s.getOpenedAt()));
var expenses=db.queryForObject("select coalesce(sum(amount),0) from expenses where hotel_id=? and branch_id=? and actor_id=? and created_at>=? and method='CASH'",BigDecimal.class,h,b,u,java.sql.Timestamp.from(s.getOpenedAt()));
s.close(s.getOpeningFloat().subtract(cash).subtract(outgoing).subtract(expenses),com.hotelmanagement.hms.shared.model.Money.nonnegative(counted));audit.record(h,b,u,"CASHIER_SHIFT_CLOSED","CASHIER_SHIFT",id);return CashierShiftResponse.from(s);} public void reconcile(UUID h,UUID b,UUID id){UUID u=scope.branch(h,b,CASHIER_RECONCILE);var s=repo.lock(id).filter(x->x.getHotelId().equals(h)&&x.getBranchId().equals(b)).orElseThrow(ApiException::notFound);s.reconcile();audit.record(h,b,u,"CASHIER_SHIFT_RECONCILED","CASHIER_SHIFT",id);}  public Object list(UUID h,UUID b){scope.branch(h,b,PAYMENT_VIEW);return db.queryForList("select s.*,u.full_name cashier_name from cashier_shifts s join users u on u.id=s.cashier_user_id where s.hotel_id=? and s.branch_id=? order by s.opened_at desc limit 100",h,b);} }
